const e="geopolitica-umana-il-confine-che-si-sfoglia",a="geopolitica-umana/il-confine-che-si-sfoglia",o="https://precious-cassata-42205a.netlify.app/geopolitica-umana/il-confine-che-si-sfoglia",i="Il confine che si sfoglia",d="",l="Dalla geopolitica alla teologia: la soglia tra lo sguardo spietato di Fabbri e la domanda sul senso ultimo del destino dei popoli.",t="geopolitica-umana",n="geopolitica-umana",s=[{type:"p",role:"p",runs:[{t:"Geopolitica Umana · Dalla lente alla soglia"}]},{type:"h",level:1,runs:[{t:"Il confine che si "},{t:"sfoglia",i:!0}],role:"p"},{type:"p",role:"p",runs:[{t:"Dalla geopolitica alla teologia: la soglia tra lo sguardo spietato di Fabbri e la domanda sul senso ultimo del destino dei popoli."}]},{type:"p",role:"p",runs:[{t:"← Verso la Teologia"}]},{type:"p",role:"p",runs:[{t:"Fabbri porta la sua analisi fino al limite estremo dell’immanenza terrestre e lì si ferma. Ma proprio lì, su quella soglia, "},{t:"inizia la teologia",b:!0},{t:". La geopolitica umana ci spiega "},{t:"come",i:!0},{t:" i popoli lottano nella prigione dello spazio e del tempo per non scomparire. La teologia entra in scena per rispondere alla domanda che Fabbri lascia aperta: perché l’anima collettiva dei popoli ha questa sete inestinguibile di eterno che le cose del mondo non riescono mai a placare del tutto?"}]},{type:"p",role:"p",runs:[{t:"La risposta teologica è che l’uomo è fatto per l’Infinito, e nessuna potenza finita — neppure la più grande delle nazioni — può colmare quel vuoto. Il confine tra le due discipline non è un muro: è una membrana che si lascia sfogliare, attraversare, indagare. Da un lato la descrizione spietata di ciò che accade; dall’altro la domanda su ciò che significa."}]},{type:"p",role:"p",runs:[{t:"«La geopolitica descrive la prigione. La teologia apre la porta.»"}]},{type:"p",role:"p",runs:[{t:"Il percorso del MetaHistoria è tutto qui: dalla "},{t:"geopolitica umana",b:!0},{t:" (i popoli e le loro paure) alla "},{t:"geopolitica dell’anima",b:!0},{t:" (il desiderio di senso che muove i popoli), fino alla "},{t:"teologia della geopolitica",b:!0},{t:" (il mistero di Dio che si nasconde e si rivela nella storia dei popoli). Ogni lente è un passo verso una comprensione più profonda del mistero dell’uomo."}]}],r=[{label:"← Indietro",title:"Verso la Teologia",href:"/geopolitica-umana/verso-la-teologia"},{label:"Avanti →",title:"Per una teologia politica",href:"/geopolitica-umana/per-una-teologia-politica"}],p=["D. Fabbri, Geopolitica umana (2023)","D. Fabbri, Sotto la pelle del mondo (2024)","D. Fabbri, Il destino dei popoli (Gribaudo, 2025)","R. Niebuhr, L’uomo morale e la società immorale (1932)","Agostino d’Ippona, La Città di Dio (426 d.C.)"],c={blocks:8,chars:1476,hash:"6e410737d0ad9d9c53c53f1f2aec56f878732d2cfb431075c26e2bde68c263e3"},u={id:e,slug:a,sourceUrl:o,title:i,kicker:"",lede:l,category:t,parentId:n,blocks:s,prevNext:r,references:p,stats:c};export{s as blocks,t as category,u as default,e as id,d as kicker,l as lede,n as parentId,r as prevNext,p as references,a as slug,o as sourceUrl,c as stats,i as title};
